      },
      {
        "segment": "part6",
        "description": "Behind-the-scenes montage of various theatre artisans—from painters to stagehands—working together to transform the stage."
      },
      {
        "segment": "outro",
        "description": "Closing shot of a live performance with harmonious lighting and set, audience captivated, fading out to the project logo."
      }
    ],
    "source_notes": [
      {
