        "timestamp": "2026-09-18",
        "note": "Highlights how live theatre depends heavily on lighting and sound to guide audience attention and engagement."
      },
      {
        "claim_id": "02-c2",
        "source_name": "Bruno Poet: Shaping Light, Story and the Space Between",
        "url": "https://www.robeuk.com/our-stories/bruno-poet-shaping-light-story-and-the-space-between",
        "timestamp": "2026-10-07",
        "note": "Describes foundational principles lighting designers use despite advances in technology."
      },
      {
        "claim_id": "02-c3",
        "source_name": "Andrew Cohen: A Behind the Scenes on Set Design",
        "url": "https://www.musiccityreview.com/2026/10/07/andrew-cohen-a-behind-the-scenes-on-set-design",
        "timestamp": "2026-10-07",
        "note": "Details the collaborative process of set design starting from script reading to adapting designs to different theater spaces."
      },
      {
        "claim_id": ["02-c4", "02-c5", "02-c8"],
        "source_name": "AuraLuxMuse: Adaptive Fusion Modeling for Aesthetic Stage Lighting Design",
